#!/usr/bin/env node
/**
 * Capture the pre-migration reference for the Figma token rail.
 *
 * Nothing about the migration can be proven unchanged without a reference taken
 * before anything moves, and a baseline regenerated by the new code proves
 * nothing. This runs the CURRENT builder and the CURRENT validators, and writes
 * three committed artifacts:
 *
 *   figma/plugin-manifest.baseline.json         exact manifest bytes + digest
 *   figma/token-rail.baseline.json              the full normalized mapping
 *   scripts/fixtures/sync-ledger/outcomes.baseline.json
 *                                               every fixture's current outcome
 *
 * The output is deterministic: no timestamps, no absolute paths, no host
 * identifiers, and prettier-formatted here so re-running is a no-op diff. Run it
 * twice — the second run must leave the working tree clean.
 */
import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import prettier from 'prettier';
import { buildExpectedVariables, flattenTokenDocument } from '@atomize-hq/figma-token-rail';
import { evaluateSyncLedgerConformance, loadAndValidateSyncLedger } from './lib/sync-ledger.mjs';

const repoRoot = process.cwd();
const manifestPath = 'figma/plugins/collider-token-sync/manifest.json';
const artifactPath = 'design-tokens/dist/figma/tokens.json';
const configPath = 'figma/token-sync.config.json';
const fixtureDir = 'scripts/fixtures/sync-ledger';

const railSpec = readJson('package.json').dependencies['@atomize-hq/figma-token-rail'];
const config = readJson(configPath);

await writeBaseline('figma/plugin-manifest.baseline.json', captureManifest());
await writeBaseline('figma/token-rail.baseline.json', captureMapping());
await writeBaseline(`${fixtureDir}/outcomes.baseline.json`, captureLedgerOutcomes());

/**
 * The manifest is a template with three substitutions and carries no generated
 * field, so it is recorded literally: nothing is excluded, and S4 stays a
 * byte-for-byte comparison rather than a comparison of a filtered subset.
 */
function captureManifest() {
  const build = spawnSync(process.execPath, ['scripts/build-figma-plugin.mjs'], {
    stdio: 'inherit',
    cwd: repoRoot,
  });
  if (build.status !== 0) {
    fail(`the current builder failed (exit ${build.status ?? 'null'}); baseline not captured`);
  }

  const bytes = fs.readFileSync(path.join(repoRoot, manifestPath));
  return {
    $comment:
      'Pre-migration reference for SPEC.md S4. Produced by the current builder; ' +
      'never regenerate this from the new one.',
    source: manifestPath,
    producedBy: 'pnpm figma:plugin:build',
    railDependency: railSpec,
    excludedFields: [],
    excludedFieldsRationale:
      'The manifest is a static template with three config substitutions. No timestamp, ' +
      'digest, path or version is interpolated into it, so no field is excluded and the ' +
      'comparison is literal.',
    byteLength: bytes.byteLength,
    sha256: crypto.createHash('sha256').update(bytes).digest('hex'),
    bytes: bytes.toString('utf8'),
  };
}

/**
 * The five summary fields are a diagnostic, not an equivalence proof: an
 * interior token's light value can change while all five stay identical. The
 * ordered variable list below is the actual reference.
 */
function captureMapping() {
  const artifact = readJson(artifactPath);
  const themeOptions = {
    extensionsNamespace: config.extensionsNamespace,
    fallbackThemeId: config.fallbackThemeId,
  };
  const leaves = flattenTokenDocument(artifact);
  const expected = buildExpectedVariables(artifact, themeOptions);

  return {
    $comment:
      'Pre-migration reference for SPEC.md S3. The expected side of the drift check comes ' +
      'from here and is never regenerated from the current artifact during preflight.',
    source: artifactPath,
    railDependency: railSpec,
    collectionName: config.collectionName,
    extensionsNamespace: config.extensionsNamespace,
    fallbackThemeId: config.fallbackThemeId,
    excludedFields: [],
    excludedFieldsRationale:
      'flattenTokenDocument walks the artifact in document order and buildExpectedVariables ' +
      'preserves it; every recorded value is resolved from committed token sources. Nothing ' +
      'is generated per run, so nothing is excluded.',
    summary: {
      leafCount: leaves.length,
      firstLeaf: leaves[0]?.name ?? null,
      lastLeaf: leaves.at(-1)?.name ?? null,
      defaultThemeId: expected.defaultThemeId,
      themeIds: expected.themeIds,
    },
    variables: expected.variables.map((variable) => ({
      name: variable.name,
      resolvedType: variable.resolvedType,
      valuesByTheme: variable.valuesByTheme,
    })),
  };
}

/**
 * Captured before T3 edits these fixtures or the validators that read them, so a
 * regression introduced by the retirement cannot become the new reference merely
 * by being recorded afterwards.
 */
function captureLedgerOutcomes() {
  const fixtures = fs
    .readdirSync(path.join(repoRoot, fixtureDir))
    .filter((name) => name.endsWith('.sync-ledger.json'))
    .sort();

  return {
    $comment:
      'Pre-retirement reference for the CT-8B ledger fixtures. Diagnostic strings are ' +
      'recorded verbatim: a fixture that goes red for a different reason is a regression, ' +
      'not a pass.',
    source: fixtureDir,
    fixtureCount: fixtures.length,
    excludedFields: [],
    excludedFieldsRationale:
      'Validator output is a pure function of the fixture on disk. No path, timestamp or ' +
      'ordering is host-dependent, so nothing is excluded.',
    fixtures: Object.fromEntries(
      fixtures.map((name) => {
        const { data, errors } = loadAndValidateSyncLedger(path.join(repoRoot, fixtureDir, name));
        return [
          name,
          {
            publishMode: data?.publish?.mode ?? null,
            valid: errors.length === 0,
            errors,
            evaluation: errors.length === 0 ? evaluateSyncLedgerConformance(data) : null,
          },
        ];
      })
    ),
  };
}

function readJson(relativePath) {
  return JSON.parse(fs.readFileSync(path.join(repoRoot, relativePath), 'utf8'));
}

async function writeBaseline(relativePath, payload) {
  const absPath = path.join(repoRoot, relativePath);
  const options = await prettier.resolveConfig(absPath);
  const formatted = await prettier.format(JSON.stringify(payload), {
    ...options,
    filepath: absPath,
  });
  fs.writeFileSync(absPath, formatted);
  process.stdout.write(`✓ ${relativePath}\n`);
}

function fail(message) {
  process.stderr.write(`capture-rail-baselines: ${message}\n`);
  process.exit(1);
}
